import gzip,glob,pandas as pd,csv
pd.set_option('display.width',250); pd.set_option('display.max_colwidth',120); pd.set_option('display.max_rows',500)
def meta(f):
    rows=[]
    for l in gzip.open(f,'rt',errors='replace'):
        if l.startswith('!series_matrix_table_begin'): break
        if l.startswith('!Sample'):
            p=next(csv.reader([l.rstrip('\n')],delimiter='\t'))
            rows.append(p)
    cols={}
    for r in rows:
        k=r[0]; i=2
        while k in cols: k=r[0]+str(i); i+=1
        cols[k]=r[1:]
    return pd.DataFrame(cols)
for f in sorted(glob.glob('studies/data/raw/*series_matrix*'))[1:]:
    d=meta(f); print('=====',f,d.shape)
    var=[c for c in d if d[c].nunique()>1 and 'protocol' not in c and 'date' not in c and 'supplementary' not in c and 'relation' not in c]
    print(d[var].to_string())

